head.script:
scwin.__isShowLog = function() {
    var log = WebSquare.logger.getLog();
    var logStep3 = log.indexOf("[STEP3][RESOURCE] Resource(XML, Skin, CSS) Load Complete") > 0;
    var logStep4 = log.indexOf("[STEP4][CREATE] WebSquare Object Creation & JS Load Complete") > 0;
    return logStep4 && logStep3;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 ctrl+마우스우클릭 > 로그보기를 실행한다.
    // verify step 1. View Log; 
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 12-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

